--
-- Table structure for table `creditos`
--

DROP TABLE IF EXISTS `creditos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `creditos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `idCliente` int NOT NULL,
  `fecha` date NOT NULL DEFAULT (curdate()),
  `valor` decimal(10,2) NOT NULL,
  `fecha_limite` date NOT NULL,
  `estado` tinyint(1) NOT NULL DEFAULT '0',
  `descripcion` varchar(255) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `factura_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_creditos_clientes` (`idCliente`),
  KEY `fk_creditos_factura` (`factura_id`),
  CONSTRAINT `fk_creditos_clientes` FOREIGN KEY (`idCliente`) REFERENCES `clientes` (`id`),
  CONSTRAINT `fk_creditos_factura` FOREIGN KEY (`factura_id`) REFERENCES `facturas` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=468 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

