CREATE TABLE `ventas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `caja_id` int NOT NULL,
  `producto_id` int DEFAULT NULL,
  `detalle` text,
  `cantidad` int NOT NULL,
  `valor` decimal(10,2) NOT NULL,
  `coste` decimal(10,2) NOT NULL DEFAULT '0.00',
  `payment_method` varchar(50) NOT NULL DEFAULT 'efectivo',
  `bank` varchar(100) DEFAULT NULL,
  `fecha` date NOT NULL,
  `hora` time NOT NULL,
  `creditoId` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `caja_id` (`caja_id`),
  KEY `producto_id` (`producto_id`),
  KEY `fk_credito` (`creditoId`),
  CONSTRAINT `fk_credito` FOREIGN KEY (`creditoId`) REFERENCES `creditos` (`id`),
  CONSTRAINT `ventas_ibfk_1` FOREIGN KEY (`caja_id`) REFERENCES `cajas` (`id`),
  CONSTRAINT `ventas_ibfk_2` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11781 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
